import numpy as np
from math import exp, sqrt


def bbs_price(S, K, r, sigma, T, n, kind="call", american=False, q=0.0):
    """CRR tree whose last step is priced by Black-Scholes."""
    dt = T / n
    u = exp(sigma * sqrt(dt))
    d = 1 / u
    p = (exp((r - q) * dt) - d) / (u - d)
    disc = exp(-r * dt)

    def payoff(s):
        return np.maximum(s - K, 0.0) if kind == "call" else np.maximum(K - s, 0.0)

    j = np.arange(n)
    s = S * u ** j * d ** (n - 1 - j)              # one step before expiry
    v = np.array([bs_price(x, K, r, sigma, dt, kind, q) for x in s])
    if american:
        v = np.maximum(v, payoff(s))
    for i in range(n - 2, -1, -1):
        v = disc * (p * v[1:] + (1 - p) * v[:-1])
        if american:
            j = np.arange(i + 1)
            v = np.maximum(v, payoff(S * u ** j * d ** (i - j)))
    return float(v[0])


def richardson_tree(S, K, r, sigma, T, n, kind="call", american=False, q=0.0):
    """Richardson extrapolation of the smoothed tree from n and 2n steps."""
    return (2 * bbs_price(S, K, r, sigma, T, 2 * n, kind, american, q)
            - bbs_price(S, K, r, sigma, T, n, kind, american, q))

