import numpy as np
from math import erf, exp, log, sqrt


def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))


def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    return K * exp(-r * T) * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)


def plain_asian_se(S, K, r, sigma, T, n_fix, n_paths, seed, q=0.0):
    """Standard error of the plain estimator on the same draws, no control."""
    z = np.random.default_rng(seed).standard_normal((n_paths, n_fix))
    dt = T / n_fix
    logs = np.cumsum((r - q - sigma ** 2 / 2) * dt + sigma * sqrt(dt) * z, axis=1)
    y = exp(-r * T) * np.maximum(S * np.exp(logs).mean(axis=1) - K, 0.0)
    return float(y.std(ddof=1) / sqrt(n_paths))
